import {STORE_KEY,labels,statuses,seed,validState,classify,createRequest,planRequest,completeRequest,metrics,today} from './core.mjs';
import {evaluation,training} from './training.mjs';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state, memoryOnly=false, storageRecovered=false;
try{const raw=localStorage.getItem(STORE_KEY);if(raw){const parsed=JSON.parse(raw);if(validState(parsed))state=parsed;else storageRecovered=true;}}catch{memoryOnly=true;storageRecovered=true;}
state??=seed();
let patientView='home',selectedCategory='',filter='all',search='',dialogId=null,recognition=null,recognitionActive=false,lastRequest=null;
const shortcuts={transport:"Je n'ai pas de moyen de transport pour venir au centre.",cost:'Je voudrais connaître les frais de la consultation.',time:'Je travaille au marché toute la matinée et je voudrais changer le créneau.',understanding:"Je n'ai pas compris quels documents apporter au centre."};
const glyph={transport:'↗',cost:'◉',time:'◷',understanding:'?'};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(next){state=next;try{localStorage.setItem(STORE_KEY,JSON.stringify(next));}catch{memoryOnly=true;toast('Stockage indisponible : cette session reste en mémoire.');}updateNav();}
function updateNav(){const m=metrics(state);$('#nav-count').textContent=m.new;document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===route())a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function dateLabel(s,opts={day:'numeric',month:'long'}){return new Date(s+'T12:00:00Z').toLocaleDateString('fr-FR',{...opts,timeZone:'Africa/Lome'});}
function pill(r){return `<span class="status-pill status-${r.category==='health'?'health':r.status}">${esc(r.category==='health'?'Contact humain requis':statuses[r.status])}</span>`;}
function route(){return ['maman','agent','preuves'].includes(location.hash.slice(1))?location.hash.slice(1):'maman';}
function listen(text){
  if(!('speechSynthesis'in window)){toast('Lecture vocale indisponible sur ce navigateur. Le texte reste affiché.');return;}
  speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='fr-FR';u.rate=.9;u.onerror=()=>toast('Lecture vocale indisponible. Le texte reste affiché.');speechSynthesis.speak(u);
}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function phone(content){return `<section class="phone" aria-label="Démonstration de l’espace maman"><div class="phone-top"><div class="mini"><span>ESPACE MAMAN</span><span>Exemple fictif</span></div><h2>Bonjour, Ama.</h2><p>Un petit pas pour vous.<br>Un grand pas pour votre famille.</p><span class="sun" aria-hidden="true">☀</span></div><div class="phone-body">${content}</div></section>`;}
function patient(){
  const own=state.appointments.filter(a=>a.womanId==='ama');
  const requests=state.requests.filter(r=>r.womanId==='ama');
  let content='';
  if(patientView==='help'){
    const options=own.filter(a=>a.status!=='completed').map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('');
    content=`<button class="text-link back" data-action="patient-home">← Mes rendez-vous</button><h2 class="form-title">Qu’est-ce qui vous<br>rend la visite difficile ?</h2><p class="hint">Choisissez une image, écrivez ou parlez en français. Un agent pourra vous écouter.</p><button class="listen" data-action="listen-help"><span aria-hidden="true">◖))</span> Écouter la question</button><form id="request-form"><label for="appointment">Le rendez-vous concerné</label><select id="appointment" name="appointment" required>${options}</select><div class="choices" role="group" aria-label="Votre difficulté">${Object.entries(shortcuts).map(([key])=>`<button type="button" class="choice" data-category="${key}" aria-pressed="false"><span class="choice-icon" aria-hidden="true">${glyph[key]}</span>${esc(labels[key])}</button>`).join('')}</div><label for="message">Votre message</label><textarea id="message" name="message" maxlength="1000" required placeholder="Par exemple : je vends au marché à cette heure…"></textarea><div class="record"><button type="button" class="secondary" data-action="dictate">♩ Dicter en français</button><button type="button" class="secondary" data-action="listen-message">◖)) Réécouter</button></div><p id="voice-status" class="hint" role="status">La dictée utilise le service vocal du navigateur, s’il est disponible. Aucun enregistrement audio n’est conservé par le prototype.</p><label class="check"><input id="consent" name="consent" type="checkbox" required><span>J’accepte de partager ce message avec l’agent dans cette démonstration. J’utilise uniquement des informations fictives.</span></label><div class="notice">Pour un symptôme ou une urgence, contactez directement une structure de santé. Aucun soignant réel ne reçoit les messages de ce prototype.</div><div id="request-error" class="error" role="alert"></div><button class="primary full" type="submit" style="margin-top:17px">Transmettre ma demande <span aria-hidden="true">→</span></button></form>`;
  }else if(patientView==='sent'&&lastRequest){
    const r=state.requests.find(r=>r.id===lastRequest);
    content=`<div class="result"><div class="success-mark" aria-hidden="true">✓</div><h3>Votre demande est enregistrée.</h3><p>Dans cette démonstration, elle apparaît maintenant dans l’espace de l’agent.</p>${r?pill(r):''}</div>${r?.category==='health'?'<div class="notice health">Ce message concerne la santé. Contactez directement une structure de soins ; n’attendez pas de réponse de ce prototype.</div>':'<p class="hint">Un agent doit vérifier le besoin avant d’organiser une réponse. Aucun rendez-vous réel n’est pris.</p>'}<button class="listen" data-action="listen-confirmation">◖)) Écouter la confirmation</button><button class="primary full" data-action="go-agent" style="margin-top:12px">Voir la demande côté agent →</button><button class="secondary full" data-action="patient-home" style="margin-top:10px">Revenir à mes rendez-vous</button>`;
  }else{
    content=`<div class="language-line"><span>Votre langue</span><span>Français · démo</span></div><button class="listen" data-action="listen-home"><span aria-hidden="true">◖))</span> Écouter mes rendez-vous</button><div class="section-label">POUR VOUS ET VOTRE ENFANT</div>${own.map(a=>`<article class="appointment"><div class="appointment-top"><div class="date-tile">${new Date(a.date+'T12:00:00Z').getUTCDate()}<small>${esc(dateLabel(a.date,{month:'short'}))}</small></div><div><h3>${esc(a.title)}</h3><p>${esc(a.facility)}<br>${esc(a.time)} · ${a.kind==='mère'?'Pour vous':'Pour votre enfant'}</p></div></div><div class="sub"><span>${a.status==='completed'?'✓ Soin confirmé':'Créneau fictif · à convenir avec le centre'}</span></div></article>`).join('')}<button class="primary full help-button" data-action="patient-help" ${own.every(a=>a.status==='completed')?'disabled':''}>J’ai besoin d’aide <span aria-hidden="true">→</span></button><p class="phone-note">Déplacement, frais, horaires, explications :<br>vous pouvez en parler.</p>${requests.length?`<div class="section-label">MES DEMANDES</div>${requests.map(r=>`<div class="request-mini">${pill(r)}<p>${esc(r.text)}</p>${r.plan?`<small>Action : ${esc(r.plan.action)}<br>${esc(dateLabel(r.plan.date))} à ${esc(r.plan.time)}</small>`:''}${r.confirmation?`<small>Réalisation confirmée le ${esc(dateLabel(r.confirmation.date))}.</small>`:''}</div>`).join('')}`:''}`;
  }
  return `<div class="patient-layout"><section class="welcome"><p class="eyebrow">PRENDRE SOIN, ENSEMBLE · TOGO</p><h1 class="hero-title">Un relais pour vous.<br><em>Chaque soin<br>à votre portée.</em></h1><p class="intro">Parce qu’un rendez-vous commence bien avant la porte du centre de santé. Une aide simple pour organiser vos soins et ceux de votre enfant.</p><div class="steps"><div class="step"><span class="step-number">01</span><div><strong>Vous expliquez ce qui vous bloque.</strong><p>Avec vos mots, à l’écrit ou à la voix.</p></div></div><div class="step"><span class="step-number">02</span><div><strong>Un agent cherche une solution avec vous.</strong><p>Un créneau, un trajet, une explication.</p></div></div><div class="step"><span class="step-number">03</span><div><strong>Votre suivi continue jusqu’au soin reçu.</strong><p>La réalisation est vérifiée auprès d’un humain.</p></div></div></div><div class="field-note"><span aria-hidden="true">◎</span><span>Projet porté par <strong>ADEC Consulting</strong>.<br>Prototype sur données fictives. Partenaires sanitaires à définir.<br>Voix en français ; langues locales et téléphonie à intégrer.</span></div></section>${phone(content)}</div>`;
}
function caseCard(r){const w=state.women.find(w=>w.id===r.womanId);return `<button class="case" data-case="${esc(r.id)}" aria-label="Ouvrir le suivi de ${esc(w.name)}"><span class="avatar">${esc(w.initials)}</span><span><h3>${esc(w.name)} <span class="muted" style="font-size:10px;font-weight:400">${esc(w.occupation)}</span></h3><span class="muted" style="font-size:10px">${esc(w.child)}</span><p>${esc(r.text)}</p><span class="case-meta"><span>${esc(labels[r.category])}</span><span>${esc(w.area)}</span></span></span><span class="case-right">${pill(r)}<span class="arrow" aria-hidden="true">↗</span></span></button>`;}
function filtered(){return state.requests.filter(r=>{const w=state.women.find(w=>w.id===r.womanId);return (filter==='all'||r.status===filter)&&(w.name+' '+r.text+' '+labels[r.category]).toLowerCase().includes(search.toLowerCase());});}
function caseList(){return filtered().map(caseCard).join('')||'<div class="empty">Aucun suivi pour cette recherche.</div>';}
function agent(){const m=metrics(state);return `${heading('LE LIEN ENTRE LA FAMILLE ET LE CENTRE','Personne ne reste sans suivi.','Retrouvez les besoins, organisez une réponse et vérifiez le soin reçu.', '<button class="secondary" data-action="export">↓ Exporter la démo</button><button class="primary" data-action="go-maman">+ Tester le parcours maman</button>')}<section class="metric-grid" aria-label="Indicateurs des données fictives"><div class="metric"><div class="metric-label">Demandes de soutien <span>↗</span></div><div class="metric-value">${m.total}</div><small>Échantillon fictif de démonstration</small></div><div class="metric"><div class="metric-label">À écouter <span>◷</span></div><div class="metric-value">${m.new}</div><small>Vérification humaine attendue</small></div><div class="metric"><div class="metric-label">Solutions organisées <span>◎</span></div><div class="metric-value">${m.planned}</div><small>La réalisation reste à confirmer</small></div><div class="metric"><div class="metric-label">Soins confirmés <span>✓</span></div><div class="metric-value">${m.completed}</div><small>${m.rate} % des demandes fictives</small></div></section><div class="workspace"><section aria-label="Dossiers de suivi"><div class="toolbar"><div class="filters" role="group" aria-label="Filtrer les suivis">${[['all','Tous les suivis'],['new','À écouter'],['planned','Organisés'],['completed','Confirmés']].map(([key,label])=>`<button class="filter ${filter===key?'active':''}" data-filter="${key}" aria-pressed="${filter===key}">${label}</button>`).join('')}</div><label class="sr-only" for="search">Rechercher un suivi</label><input id="search" type="search" placeholder="Rechercher une maman, un besoin…" value="${esc(search)}"></div><div class="cases" id="case-list">${caseList()}</div></section><aside><div class="aside-card"><p class="eyebrow" style="font-size:8px">LE SENS DU RELAIS</p><h3>Un message devient<br>une action concrète.</h3><ol><li>Écouter et vérifier le besoin.</li><li>Convenir d’une réponse avec la mère et le centre.</li><li>Vérifier la réalisation du soin.</li></ol></div><div class="privacy-note">◎ <strong>Un espace de démonstration.</strong><br>Les dossiers restent dans ce navigateur. Les deux espaces partagent ces données locales ; aucun centre réel n’est connecté.</div><button class="demo-shortcut" data-action="go-proofs">Voir ce qui fonctionne réellement ↗</button></aside></div>`;}
function proofs(){
  const results=evaluation.map(([expected,text])=>({expected,...classify(text)})),correct=results.filter(r=>r.label===r.expected).length,abstained=results.filter(r=>r.label==='human').length;
  return `${heading('PROTOTYPE 0.1 · ADEC CONSULTING','Une preuve de fonctionnement.','Coordonner un parcours mère-enfant, puis vérifier que le soin a été reçu.')}<div class="proof-layout"><div><section class="proof-card"><span class="tag">DONNÉES FICTIVES</span><span class="tag">FONCTIONNE LOCALEMENT</span><h2 style="margin-top:19px">Ce que vous pouvez tester.</h2>${[['Demande et consentement','Opérationnel'],['Classement statistique des messages en français','Opérationnel · expérimental'],['Organisation d’une réponse par l’agent','Opérationnel'],['Confirmation et historique du soin','Opérationnel'],['Lecture vocale en français','Selon le navigateur'],['Consultation hors connexion après chargement','Cache local'],['Vrais appels, SMS et échanges avec un centre','À intégrer'],['Reconnaissance et contenus en langues locales','À développer et valider'],['Comptes utilisateurs et données partagées entre appareils','À intégrer']].map(([cap,status])=>`<div class="capability ${status.startsWith('À')?'pending':''}"><span>${cap}</span><span>${status}</span></div>`).join('')}<p class="legal-line">La dictée vocale, si elle est proposée, nécessite votre activation et peut utiliser un service du navigateur via internet. Elle ne constitue pas un moteur vocal local. L’application n’enregistre pas de fichier audio.</p></section><section class="proof-card"><h2>Quatre minutes pour comprendre.</h2><ol style="padding-left:19px"><li>Dans « Espace maman », choisissez « J’ai besoin d’aide ».</li><li>Décrivez un obstacle fictif et donnez votre accord.</li><li>Ouvrez la demande dans « Suivi communautaire ».</li><li>Enregistrez une action et un créneau convenus.</li><li>Confirmez le soin sur une date passée ou aujourd’hui, puis retrouvez le résultat côté maman.</li></ol><div class="demo-actions"><button class="primary" data-action="go-maman">Commencer la démonstration →</button><button class="secondary" data-action="export">↓ Exporter les données</button><button class="danger-button" data-action="reset">Réinitialiser la démo</button></div></section><section class="proof-card"><h2>Du prototype au terrain.</h2><p><strong>Porteur : ADEC Consulting, Togo.</strong> Statut juridique et immatriculation à documenter. Équipe clinique et partenaires sanitaires à définir.</p><p>Avant un usage réel : validation avec des soignants et des femmes, étude linguistique, gestion des accès, consentement adapté, hébergement sécurisé, accords télécom et procédures de prise en charge. Aucun résultat terrain n’est revendiqué.</p><a class="source-link" href="https://www.unicef.org/innovation/FemTechCall" target="_blank" rel="noopener noreferrer">Consulter l’appel officiel UNICEF ↗</a></section></div><div><section class="proof-card"><p class="eyebrow">UNE IA LIMITÉE À L’ORGANISATION</p><h2>Comprendre le blocage.</h2><p>Un classificateur Naïve Bayes est entraîné dans le navigateur sur <strong>${Object.values(training).flat().length} phrases synthétiques</strong>. Il suggère une catégorie : déplacement, coût, disponibilité ou compréhension.</p><p>En cas d’incertitude, il s’abstient. Toute suggestion attend une vérification humaine. Le score du modèle n’est pas une probabilité clinique.</p><label for="lab-message">Essayer un message fictif en français</label><textarea id="lab-message" maxlength="1000">Je vends au marché à cette heure et je voudrais changer le créneau.</textarea><button class="primary full" data-action="classify" style="margin-top:12px">Analyser l’obstacle →</button><div id="lab-output" class="lab-output" role="status" aria-live="polite">Le résultat apparaîtra ici. Aucun message n’est transmis.</div></section><section class="proof-card"><p class="eyebrow">ÉVALUATION SYNTHÉTIQUE</p><div class="evaluation">${correct} / ${evaluation.length}</div><p>Catégories correctes sur un jeu séparé de ${evaluation.length} phrases fictives ; ${abstained} abstention${abstained>1?'s':''}. Exemples rédigés par l’équipe de développement, sans validation indépendante.</p><div class="notice">Ce résultat technique ne mesure ni la compréhension des langues togolaises, ni l’efficacité médicale, ni un impact sur les soins.</div></section><section class="proof-card"><h2>Conçu pour la confiance.</h2><ul><li>Aucun diagnostic, prescription ou décision clinique automatisée.</li><li>Les mots de santé repérés déclenchent une reprise humaine.</li><li>Aucune vraie patiente, aucun numéro de téléphone, aucune géolocalisation.</li><li>Aucun suivi publicitaire ni bibliothèque distante.</li><li>Prototype et exemples sous licence MIT, à publier dans un dépôt accessible aux évaluateurs.</li></ul><p class="legal-line">La détection de mots de santé est une règle prudente et incomplète. Elle ne remplace jamais une évaluation médicale. Cette version n’est pas destinée à la prise en charge réelle.</p></section></div></div>`;
}
function render(){stopRecognition();updateNav();$('#main').innerHTML=route()==='agent'?agent():route()==='preuves'?proofs():patient();connectionStatus();}
function connectionStatus(){const el=$('#connection');if(memoryOnly)el.textContent='Session en mémoire';else if(!navigator.onLine)el.textContent='Hors connexion';else if(navigator.serviceWorker?.controller)el.textContent='Disponible hors connexion';else el.textContent='Données sur cet appareil';}
function openCase(id){
  const r=state.requests.find(r=>r.id===id);if(!r)return;dialogId=id;
  const w=state.women.find(w=>w.id===r.womanId),d=$('#case-dialog');
  const defaultAction={time:'Convenir d’un créneau compatible avec l’activité, après vérification auprès du centre.',transport:'Vérifier une solution de déplacement avec la mère et le relais local.',cost:'Vérifier les frais et les dispositifs de prise en charge auprès du centre.',understanding:'Expliquer oralement les démarches et vérifier qu’elles sont comprises.',human:'Écouter la mère, préciser son besoin et convenir d’une réponse.'}[r.category]||'';
  d.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><div><p class="eyebrow">DOSSIER FICTIF · VÉRIFICATION HUMAINE</p><h2 id="dialog-title">${esc(w.name)}</h2><p class="hint" style="margin-top:0">${esc(w.occupation)} · ${esc(w.child)}</p></div><button class="close" data-action="close-dialog" aria-label="Fermer le dossier">×</button></div>${pill(r)}<blockquote class="quote">« ${esc(r.text)} »</blockquote><div class="mini-label">${r.classification.source==='explicit-choice'?'Choix explicite de la personne':'Suggestion à vérifier par l’agent'}</div><p style="font-size:13px;margin-top:6px">${esc(labels[r.category])}${r.classification.source==='abstention'?' · classement incertain':''}</p>${r.category==='health'?'<div class="notice health">Ce message concerne potentiellement la santé. Ce prototype ne réalise aucun triage clinique et ne prévient aucun soignant réel. Dans un service réel, un protocole humain dédié serait nécessaire. Ne retardez pas un contact direct avec une structure de soins.</div>':r.status==='completed'?`<div class="result"><div class="success-mark" aria-hidden="true">✓</div><h3>Soin confirmé dans la démonstration.</h3><p>Date déclarée : ${esc(dateLabel(r.confirmation.date))}<br>Vérification : ${r.confirmation.source==='centre'?'centre partenaire':'agent communautaire'}.</p></div>`:r.status==='planned'?`<div class="plan-summary"><strong style="font-size:13px">${esc(dateLabel(r.plan.date))} à ${esc(r.plan.time)}</strong><p>${esc(r.plan.action)}</p><p>Frais : ${esc(r.plan.cost)}</p></div><form id="complete-form"><h3>Le soin a-t-il été reçu ?</h3><p class="hint">La confirmation porte sur la réalisation du soin, pas seulement sur le déplacement ou l’appel.</p><div class="two-columns"><div><label for="care-date">Date du soin</label><input id="care-date" name="date" type="date" min="${esc(r.createdAt.slice(0,10))}" max="${today()}" value="${today()}" required></div><div><label for="care-source">Source de vérification</label><select id="care-source" name="source" required><option value="">Choisir…</option><option value="centre">Centre partenaire · démo</option><option value="asc">Agent communautaire · démo</option></select></div></div><label class="check"><input name="verified" type="checkbox" required><span>Je confirme avoir vérifié la réalisation du soin auprès de cette source, dans le scénario fictif.</span></label><div id="case-error" class="error" role="alert"></div><button class="primary full" type="submit">✓ Confirmer le soin reçu</button></form>`:`<form id="plan-form"><h3>Convenir d’une réponse.</h3><p class="hint">Les propositions doivent être vérifiées avec la mère et le centre. Aucune réservation réelle n’est effectuée.</p><div class="two-columns"><div><label for="plan-date">Créneau convenu</label><input id="plan-date" name="date" type="date" min="${today()}" value="${today()}" required></div><div><label for="plan-time">Heure</label><input id="plan-time" name="time" type="time" value="09:00" required></div></div><label for="plan-action">Action convenue</label><textarea id="plan-action" name="action" maxlength="600" required>${esc(defaultAction)}</textarea><label for="plan-cost">Frais ou prise en charge vérifiés</label><input id="plan-cost" name="cost" maxlength="120" placeholder="À vérifier auprès du centre"><label class="check"><input name="agreed" type="checkbox" required><span>Dans le scénario, la mère et le centre ont accepté cette organisation.</span></label><div id="case-error" class="error" role="alert"></div><button class="primary full" type="submit">Enregistrer la solution →</button></form>`}<div class="divider"></div><h3>Historique du suivi</h3><ol class="timeline">${r.history.map(h=>`<li>${esc(h.text)}<small>${esc(new Date(h.at).toLocaleString('fr-FR',{timeZone:'Africa/Lome',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</small></li>`).join('')}</ol></div>`;
  if(!d.open)d.showModal();
}
function closeDialog(){stopRecognition();$('#case-dialog').close();dialogId=null;}
function exportDemo(){const data={...state,exportedAt:new Date().toISOString(),notice:'SYNTHETIC DEMONSTRATION DATA ONLY. No field validation. No actual care delivery.',projectOwner:'ADEC Consulting',metrics:metrics(state)};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='relais-maman-demo-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export des données fictives téléchargé.');}
function stopRecognition(){if(recognition){recognition.onend=null;recognition.onerror=null;recognition.abort();recognition=null;}recognitionActive=false;}
function dictate(){
  if(recognitionActive){recognition?.stop();return;}
  const API=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!API){toast('Dictée indisponible ici. Utilisez un bouton ou écrivez votre message.');return;}
  if(!navigator.onLine){toast('La dictée peut nécessiter internet. Utilisez les boutons ou le texte hors connexion.');return;}
  recognition=new API();recognition.lang='fr-FR';recognition.interimResults=false;recognition.continuous=false;
  recognition.onresult=e=>{if($('#message'))$('#message').value=e.results[0][0].transcript;};
  recognition.onstart=()=>{recognitionActive=true;const b=$('[data-action="dictate"]');if(b){b.classList.add('recording');b.textContent='■ Arrêter la dictée';}$('#voice-status').textContent='Écoute en cours. Utilisez uniquement un exemple fictif.';};
  recognition.onend=()=>{recognitionActive=false;const b=$('[data-action="dictate"]');if(b){b.classList.remove('recording');b.textContent='♩ Dicter en français';}if($('#voice-status'))$('#voice-status').textContent='Vérifiez le texte reconnu avant de transmettre. Aucun fichier audio n’est conservé.';};
  recognition.onerror=e=>{if($('#voice-status'))$('#voice-status').textContent='Dictée indisponible ou interrompue. Vous pouvez utiliser les boutons et le texte.';};
  try{recognition.start();}catch{toast('Impossible de démarrer la dictée. Utilisez les boutons ou le texte.');}
}
document.addEventListener('click',e=>{
  if(e.target.closest('a[href="#maman"]')){patientView='home';if(route()==='maman')render();}
  const cat=e.target.closest('[data-category]');if(cat){selectedCategory=cat.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>{const on=b===cat;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});$('#message').value=shortcuts[selectedCategory];return;}
  const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return;}
  const c=e.target.closest('[data-case]');if(c){openCase(c.dataset.case);return;}
  const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
  if(action==='patient-help'){patientView='help';selectedCategory='';render();$('.phone').scrollIntoView({behavior:'smooth',block:'start'});$('#appointment')?.focus({preventScroll:true});}
  if(action==='patient-home'){patientView='home';render();}
  if(action==='go-agent'){filter='all';search='';location.hash='agent';if(route()==='agent')render();}
  if(action==='go-maman'){patientView='home';location.hash='maman';if(route()==='maman')render();}
  if(action==='go-proofs')location.hash='preuves';
  if(action==='listen-home'){const apps=state.appointments.filter(a=>a.womanId==='ama');listen('Bonjour Ama. Ceci est une démonstration. '+apps.map(a=>a.title+', le '+dateLabel(a.date)+' à '+a.time+'. '+(a.status==='completed'?'Soin confirmé.':'')).join(' ')+' Si vous avez besoin d’aide, appuyez sur le bouton J’ai besoin d’aide.');}
  if(action==='listen-help')listen('Qu’est-ce qui rend votre visite difficile ? Le déplacement, le coût des soins, les horaires, ou les explications ? Choisissez un bouton ou expliquez votre besoin. Cette démonstration utilise seulement des données fictives.');
  if(action==='listen-message')listen($('#message').value||'Choisissez un besoin ou écrivez un message.');
  if(action==='listen-confirmation')listen('Votre demande est enregistrée dans cette démonstration. Vous pouvez maintenant la retrouver dans l’espace de l’agent. Aucun soignant réel ne reçoit ce message.');
  if(action==='dictate')dictate();
  if(action==='close-dialog')closeDialog();
  if(action==='export')exportDemo();
  if(action==='reset'){const d=$('#case-dialog');d.innerHTML='<div class="dialog-inner"><div class="dialog-top"><h2 id="dialog-title">Recommencer la démo ?</h2><button class="close" data-action="close-dialog" aria-label="Fermer">×</button></div><p>Seules les données fictives de cette démonstration seront remplacées par les exemples de départ.</p><div class="demo-actions"><button class="danger-button" data-action="confirm-reset">Oui, réinitialiser les exemples</button><button class="secondary" data-action="close-dialog">Conserver ma démo</button></div></div>';d.showModal();}
  if(action==='confirm-reset'){closeDialog();save(seed());patientView='home';filter='all';search='';render();toast('Démonstration réinitialisée.');}
  if(action==='classify'){const t=$('#lab-message').value.trim();if(!t){$('#lab-output').textContent='Écrivez un exemple fictif pour lancer l’analyse.';return;}const r=classify(t);$('#lab-output').textContent=r.label==='health'?'Message de santé détecté par une règle : orientation humaine directe. Aucun triage clinique, aucune alerte envoyée.':r.label==='human'?'Le modèle s’abstient : ce message doit être écouté par une personne.':'Suggestion : '+labels[r.label]+'. À vérifier par l’agent. Modèle statistique expérimental, en français uniquement.';}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#case-list').innerHTML=caseList();}if(e.target.id==='message'){selectedCategory='';document.querySelectorAll('[data-category]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});}});
document.addEventListener('submit',e=>{
  if(!['request-form','plan-form','complete-form'].includes(e.target.id))return;e.preventDefault();const data=new FormData(e.target);
  try{
    if(e.target.id==='request-form'){stopRecognition();const next=createRequest(state,{womanId:'ama',appointmentId:data.get('appointment'),text:data.get('message'),category:selectedCategory,consent:data.get('consent')==='on'});lastRequest=next.requests[0].id;save(next);patientView='sent';render();$('.phone').scrollIntoView({behavior:'smooth',block:'start'});}
    if(e.target.id==='plan-form'){if(!data.get('agreed'))throw Error('L’organisation doit être convenue avec la mère et le centre.');save(planRequest(state,dialogId,{date:data.get('date'),time:data.get('time'),action:data.get('action'),cost:data.get('cost')}));render();openCase(dialogId);toast('Solution enregistrée dans la démonstration.');}
    if(e.target.id==='complete-form'){save(completeRequest(state,dialogId,{date:data.get('date'),source:data.get('source'),verified:data.get('verified')==='on'}));render();openCase(dialogId);toast('Soin confirmé ; les indicateurs ont été mis à jour.');}
  }catch(error){const target=e.target.id==='request-form'?$('#request-error'):$('#case-error');if(target)target.textContent=error.message;}
});
$('#case-dialog').addEventListener('click',e=>{if(e.target===$('#case-dialog'))closeDialog();});
$('#case-dialog').addEventListener('cancel',()=>{dialogId=null;});
window.addEventListener('hashchange',()=>{closeDialog();window.speechSynthesis?.cancel?.();render();window.scrollTo({top:0});});
window.addEventListener('online',connectionStatus);window.addEventListener('offline',connectionStatus);
window.addEventListener('storage',e=>{if(e.key===STORE_KEY){try{const incoming=JSON.parse(e.newValue);if(validState(incoming)){state=incoming;closeDialog();render();toast('Démonstration actualisée depuis un autre onglet.');}}catch{}}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(connectionStatus).catch(()=>toast('Cache hors connexion indisponible ; le prototype reste utilisable en ligne.'));
navigator.serviceWorker?.addEventListener('controllerchange',connectionStatus);
render();if(storageRecovered)toast('Les données locales étaient indisponibles ou invalides ; les exemples fictifs ont été restaurés.');
